<?php require dirname(__DIR__,2).'/app/bootstrap.php';requireAdmin();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}verifyCsrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if(!$id){http_response_code(422);exit('Invalid ID');}$active=db()->prepare("SELECT COUNT(*) FROM rental_order_items oi JOIN rental_orders o ON o.id=oi.order_id WHERE oi.product_id=? AND o.status IN ('reserved','out')");$active->execute([$id]);if((int)$active->fetchColumn()>0){http_response_code(409);exit('Cannot delete a product with active rental orders.');}$q=db()->prepare('DELETE FROM products WHERE productId=?');$q->execute([$id]);header('Location: /admin/index.php');exit;
